 @Test void allocationPreviewReservationAndCheckout()throws Exception{String bid=bed("1");Map<String,Object> b=allocation(bid);call(post("/college-work/allocation"),c,b,200);assertEquals("available",s(store.get("erp_bed",bid),"status"));b.put("confirm",true);call(post("/college-work/allocation"),c,b,200);assertEquals("reserved",s(store.get("erp_bed",bid),"status"));call(post("/college-work/allocation"),c,b,409);Map<String,Object> h=store.all("erp_housing").get(0);call(post("/college-work/housing/"+s(h,"id")),c,map("action","confirm_handover","reason","现场核验","actualHandover",true,"handoverReference","交接1","version",h.get("version")),200);assertEquals("occupied",s(store.get("erp_bed",bid),"status"));Map<String,Object> checkout=row(call(post("/college-work/housing"),c,map("studentId","s","type","checkout","content","退宿"),200));checkout=row(call(post("/college-work/housing/"+s(checkout,"id")),c,map("action","approve","reason","允许退宿","version",checkout.get("version")),200));call(post("/college-work/housing/"+s(checkout,"id")),c,map("action","confirm_handover","reason","交接完成","actualHandover",true,"handoverReference","退宿1","version",checkout.get("version")),200);assertEquals("available",s(store.get("erp_bed",bid),"status"));}
 @Test void allocationInsufficientOrWrongConditionRollsBack()throws Exception{String bid=bed("1");Map<String,Object> b=allocation(bid);b.put("studentIds",Arrays.asList("s","s2"));b.put("confirm",true);call(post("/college-work/allocation"),c,b,409);b.put("studentIds",Arrays.asList("s"));b.put("conditions","男生");call(post("/college-work/allocation"),c,b,409);assertEquals("available",s(store.get("erp_bed",bid),"status"));assertTrue(store.all("erp_housing").isEmpty());}
 @Test void carePrivacyAndPartyStageVerification()throws Exception{Map<String,Object> b=map("clientId",UUID.randomUUID().toString(),"title","关怀跟进","studentId","s","content","必要观察事实","type","followup","dueAt","2099-01-01T00:00:00Z");Map<String,Object> care=list(call(post("/college-work/care"),c,b,200)).get(0);assertTrue(list(call(get("/college-work/care"),s,null,200)).isEmpty());assertTrue(list(call(get("/college-work/care"),admin,null,200)).isEmpty());assertTrue(list(call(get("/college-work/care"),leader,null,200)).isEmpty());call(post("/college-work/share"),c,map("module","care","recordId",s(care,"id"),"recipientIds",Arrays.asList("leader")),409);b=map("clientId",UUID.randomUUID().toString(),"title","入党培养","studentId","s","track","party","basis","学校规程","dueAt","2099-01-01T00:00:00Z");Map<String,Object> party=list(call(post("/college-work/party"),c,b,200)).get(0);Map<String,Object> advance=map("action","advance","reason","核验完成","version",party.get("version"),"dueAt","2099-02-01T00:00:00Z","basis","考察材料");call(post("/college-work/party/"+s(party,"id")+"/action"),leader,advance,409);advance.put("verified",true);party=row(call(post("/college-work/party/"+s(party,"id")+"/action"),leader,advance,200));assertEquals(1L,((Number)party.get("stage")).longValue());}
 @Test void importPreviewAndDuplicateRowsAreAtomic()throws Exception{String csv="campus,building,room,bed,conditions,source\n主校区,1,101,1,女生,台账\n";MockMultipartFile f=new MockMultipartFile("file","beds.csv","text/csv",csv.getBytes("UTF-8"));call(multipart("/college-work/imports/beds").file(f),c,null,200);assertTrue(store.all("erp_bed").isEmpty());call(multipart("/college-work/imports/beds").file(f).param("confirm","true"),c,null,200);assertEquals(1,store.all("erp_bed").size());call(multipart("/college-work/imports/beds").file(f).param("confirm","true"),c,null,409);assertEquals(1,store.all("erp_bed").size());}
 @Test void archiveRequiresCompletionAndRetainsScope()throws Exception{Map<String,Object> t=list(call(post("/college-work/tasks"),c,taskBody(),200)).get(0);Map<String,Object> b=map("clientId",UUID.randomUUID().toString(),"title","任务归档","sourceModule","tasks","sourceId",s(t,"id"));call(post("/college-work/archive"),c,b,409);t.put("status","completed");store.save("college_tasks",t);call(post("/college-work/archive"),c,b,200);assertTrue(list(call(get("/college-work/archive"),other,null,200)).isEmpty());}
 @Test void retryRechecksPermissionAndAiSupportsLeaders()throws Exception{Map<String,Object> body=taskBody();call(post("/college-work/tasks"),c,body,200);Map<String,Object> teacher=store.get("user","c");teacher.put("className","different");store.save("user",teacher);call(post("/college-work/tasks"),c,body,409);for(String action:Arrays.asList("text_write","text_polish")){Map<String,Object> result=row(call(post("/ai/assist"),leader,map("action",action,"prompt","工作说明","details"," 已知事实  内容 "),200));assertEquals("template",s(result,"mode"));assertFalse(s(result,"content").isEmpty());}}
